package com.therighthon.rnr.common.recipe;
import com.google.gson.JsonObject; import com.mojang.datafixers.util.Either; import net.minecraft.core.BlockPos; import net.minecraft.network.FriendlyByteBuf; import net.minecraft.network.chat.Component; import net.minecraft.resources.ResourceLocation; import net.minecraft.util.GsonHelper; import net.minecraft.world.InteractionHand; import net.minecraft.world.InteractionResult; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.crafting.Ingredient; import net.minecraft.world.item.crafting.RecipeSerializer; import net.minecraft.world.item.crafting.RecipeType; import net.minecraft.world.item.context.BlockPlaceContext; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.phys.BlockHitResult; import net.minecraftforge.registries.ForgeRegistries; import org.jetbrains.annotations.Nullable; import com.therighthon.rnr.common.RNRPlayerData;
import java.util.*;
public class MattockRecipe extends RNRSimpleBlockRecipe { public static final List<MattockRecipe> CACHE=new ArrayList<>(); private final RNRMattockMode mode; private final Ingredient itemIngredient; private final RNRItemStackProvider extraDrop; public MattockRecipe(ResourceLocation id,RNRBlockIngredient in,BlockState out,RNRMattockMode m,@Nullable Ingredient ii,RNRItemStackProvider drop){super(id,in,out);mode=m;itemIngredient=ii;extraDrop=drop;} public static MattockRecipe getRecipe(BlockState s,ItemStack held,RNRMattockMode m){for(MattockRecipe r:CACHE)if(r.matches(s,held,m))return r;return null;} public boolean matches(BlockState s,ItemStack held,RNRMattockMode m){return mode==m&&ingredient.test(s)&&(itemIngredient==null||itemIngredient.test(held));} public RNRMattockMode getMode(){return mode;} public Ingredient getItemIngredient(){return itemIngredient;} public ItemStack getExtraDrop(ItemStack tool){return extraDrop.getSingleStack(tool);} @Override public RecipeSerializer<?> getSerializer(){return RNRRecipeSerializers.MATTOCK_RECIPE.get();} @Override public RecipeType<?> getType(){return RNRRecipeTypes.MATTOCK_RECIPE.get();}
 public static Either<BlockState,InteractionResult> computeResult(Player p,BlockState state,BlockHitResult hit,boolean inform){MattockRecipe r=getRecipe(state,p.getMainHandItem(),RNRPlayerData.getMode(p));if(r==null){if(inform)p.displayClientMessage(Component.translatable("rnr.mattock.no_recipe"),true);return Either.right(InteractionResult.PASS);} BlockState out=r.getBlockCraftingResult(state);out=out.getBlock().getStateForPlacement(new BlockPlaceContext(p,InteractionHand.MAIN_HAND,new ItemStack(out.getBlock()),hit));return out==null?Either.right(InteractionResult.FAIL):Either.left(out);}
 public static class Serializer implements RecipeSerializer<MattockRecipe>{
  public MattockRecipe fromJson(ResourceLocation id,JsonObject j){RNRBlockIngredient i=RNRBlockIngredient.fromJson(j.get("ingredient"));BlockState o=ForgeRegistries.BLOCKS.getValue(ResourceLocation.tryParse(GsonHelper.getAsString(j,"result"))).defaultBlockState();RNRMattockMode m=RNRMattockMode.valueOf(GsonHelper.getAsString(j,"mode","smooth").toUpperCase(Locale.ROOT));Ingredient ii=j.has("item_ingredient")?Ingredient.fromJson(j.get("item_ingredient")):null;RNRItemStackProvider d=j.has("extra_drop")?RNRItemStackProvider.fromJson(j.getAsJsonObject("extra_drop")):RNRItemStackProvider.empty();MattockRecipe r=new MattockRecipe(id,i,o,m,ii,d);CACHE.add(r);return r;}
  @Nullable public MattockRecipe fromNetwork(ResourceLocation id,FriendlyByteBuf b){RNRBlockIngredient i=RNRBlockIngredient.fromNetwork(b);BlockState o=ForgeRegistries.BLOCKS.getValue(b.readResourceLocation()).defaultBlockState();RNRMattockMode m=b.readEnum(RNRMattockMode.class);Ingredient ii=b.readBoolean()?Ingredient.fromNetwork(b):null;RNRItemStackProvider d=RNRItemStackProvider.fromNetwork(b);MattockRecipe r=new MattockRecipe(id,i,o,m,ii,d);CACHE.add(r);return r;}
  public void toNetwork(FriendlyByteBuf b,MattockRecipe r){r.ingredient.toNetwork(b);b.writeResourceLocation(ForgeRegistries.BLOCKS.getKey(r.outputState.getBlock()));b.writeEnum(r.mode);b.writeBoolean(r.itemIngredient!=null);if(r.itemIngredient!=null)r.itemIngredient.toNetwork(b);r.extraDrop.toNetwork(b);}
 }
}
